function maxSum(nums, k) {
  const MOD = 1000000007n;
  const BITS = 30;
  const count = new Array(BITS).fill(0);
  for (const num of nums) {
    for (let bit = 0; bit < BITS; bit++) {
      if ((num >> bit) & 1) {
        count[bit]++;
      }
    }
  }
  let total = 0n;
  for (let pick = 0; pick < k; pick++) {
    let value = 0;
    for (let bit = 0; bit < BITS; bit++) {
      if (count[bit] > 0) {
        value |= 1 << bit;
        count[bit]--;
      }
    }
    const big = BigInt(value);
    total = (total + big * big) % MOD;
  }
  return Number(total);
}

