function maxSum(nums, k) {
  const score = arr => [...arr].sort((a, b) => b - a).slice(0, k).reduce((s, v) => s + BigInt(v) ** 2n, 0n);
  let best = 0n;
  if (nums.length <= 4 && nums.every(v => v < 16)) {
    // Tiny input: explore every array the operation can reach and score each one exactly.
    const seen = new Set([nums.join(',')]);
    const queue = [nums.slice()];
    while (queue.length) {
      const arr = queue.pop();
      const s = score(arr);
      if (s > best) best = s;
      for (let i = 0; i < arr.length; i++) {
        for (let j = 0; j < arr.length; j++) {
          if (i === j) continue;
          const next = arr.slice();
          next[i] = arr[i] & arr[j];
          next[j] = arr[i] | arr[j];
          const key = next.join(',');
          if (!seen.has(key)) { seen.add(key); queue.push(next); }
        }
      }
    }
  } else {
    // Otherwise apply the operation pair by pair, OR to the front, until nothing changes.
    const arr = nums.slice();
    let changed = true;
    while (changed) {
      changed = false;
      for (let i = 0; i < arr.length; i++) {
        for (let j = i + 1; j < arr.length; j++) {
          const high = arr[i] | arr[j], low = arr[i] & arr[j];
          if (high !== arr[i]) { arr[i] = high; arr[j] = low; changed = true; }
        }
      }
    }
    best = score(arr);
  }
  return Number(best % 1000000007n);
}

