function generate(rand, size) {
  if (size === 'large') {
    const n = 2000;
    const style = Math.floor(rand() * 3);
    const nums = Array.from({ length: n }, () => {
      if (style === 0) return 1 + Math.floor(rand() * 1000000000);
      if (style === 1) return 1 << Math.floor(rand() * 29);
      return 1000000000 - Math.floor(rand() * 1000);
    });
    const k = 1 + Math.floor(rand() * n);
    return [nums, k];
  }
  const n = 1 + Math.floor(rand() * 4);
  const top = rand() < 0.5 ? 7 : 15;
  const nums = Array.from({ length: n }, () => 1 + Math.floor(rand() * top));
  const k = 1 + Math.floor(rand() * n);
  return [nums, k];
}
